import java.util.*;
import java.io.*;

public class Main {
    static long[] countSentences(String[] wordSet, String[][] sentences) {
        // Write your solution here
        return new long[sentences.length];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        String[] wordSet = new String[n];
        for (int i = 0; i < n; i++) wordSet[i] = st.nextToken();
        int m = Integer.parseInt(st.nextToken());
        String[][] sentences = new String[m][];
        for (int i = 0; i < m; i++) {
            int k = Integer.parseInt(st.nextToken());
            sentences[i] = new String[k];
            for (int j = 0; j < k; j++) sentences[i][j] = st.nextToken();
        }
        long[] res = countSentences(wordSet, sentences);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
